 update(item.id,key,value,false,{reconcileVoltage:true,beforeCommit:()=>{
  restoreReferenceField(item,key);
  if(item.kind==='cable'&&['rPerM','xPerM'].includes(key)){item.frequencyOverride=false;item.allowIdeal=false;if(Object.hasOwn(item,'loopImpedanceBasis'))item.loopImpedanceBasis='';}
 }});
