function diagramPanel(full=false){
 const missing=diagramGeometry(project).missing,chosen=itemById(selection);
 const instruction=placementKind==='cable'?'Drag from one busbar to another to connect them. Click empty space to add a feeder and its downstream bus.':placementKind?'Move the preview, then click the drawing or a bus to place '+names[placementKind]+'.':drawingConnection?.itemId?'Click the bus to use for this connection.':drawingConnection?(drawingConnection.from?'Click the destination bus, or drag to it.':'Drag from one busbar to another, or click the starting bus and destination bus.'):'Double-click for properties · drag bus ends to resize · drag symbols to move';
 return `<section class="network-panel${full?' full-diagram':''}"><div class="panel-heading"><div><span class="eyebrow">CONNECTED ELECTRICAL MODEL</span><h2>Your electrical one-line</h2></div><div class="actions"><button data-action="blank">New SLD</button><button data-action="layout" title="Arrange symbols by electrical connections">Arrange</button><button data-plant-builder="open" title="Generate a full PV or BESS plant one-line from block data">Build plant</button><button data-equipment-table="open" title="Export or update all equipment as a spreadsheet table">Equipment table</button></div></div><div class="diagram-toolbar" role="toolbar" aria-label="Diagram controls"><div class="diagram-tools"><button data-action="diagram-out" aria-label="Zoom out">−</button><button data-action="diagram-fit">Fit</button><button data-action="diagram-in" aria-label="Zoom in">+</button></div><button data-action="diagram-focus" title="Zoom to the selected equipment">Focus</button><label class="diagram-find"><input id="diagram-find" type="search" value="${esc(findQuery)}" placeholder="Find bus or equipment" aria-label="Find a bus or equipment by name; Enter shows the next match" autocomplete="off" spellcheck="false"></label>${findStatus?`<span class="diagram-find-status" role="status">${esc(findStatus)}</span>`:''}<select id="connection-kind" aria-label="Connection type"><option value="cable" ${connectionKind==='cable'?'selected':''}>Cable</option><option value="transformer" ${connectionKind==='transformer'?'selected':''}>Transformer</option><option value="link" ${connectionKind==='link'?'selected':''}>Direct connection</option></select><button data-action="connect-buses" aria-pressed="${Boolean(drawingConnection)&&!drawingConnection.itemId}" ${project.buses.length<2?'disabled':''}>Connect buses</button><button data-action="diagram-currents" aria-pressed="${showBranchCurrents}">${showBranchCurrents?'Currents on':'Show currents'}</button><button data-action="diagram-export" title="Download this diagram as an SVG">SVG</button></div><div class="diagram-selection-actions" role="toolbar" aria-label="Selected diagram equipment"><span id="diagram-selection-name">${chosen?esc(chosen.name):'Select equipment on the drawing'}</span>${chosen?`<button data-edit-equipment="${esc(chosen.id)}">Edit data</button><button data-duplicate="${esc(chosen.id)}">Duplicate</button><button class="danger" data-delete="${esc(chosen.id)}">Delete</button>`:''}</div><div class="drawing-instruction" role="status"><span>${esc(instruction)}</span>${placementKind||drawingConnection?'<button data-action="draw-select">Cancel</button>':''}</div>${missing.length?`<div class="diagram-missing"><strong>${missing.length} missing ${missing.length===1?'connection':'connections'}</strong>${missing.slice(0,4).map(item=>`<button data-edit-equipment="${item.id}">${esc(item.name)} → Connect</button>`).join('')}</div>`:''}${(()=>{const g=diagramGeometry(project),v=diagramViewport||g.bounds;if(g.items.length<=LARGE_DIAGRAM_ITEMS)return '';return `<p class="diagram-overview-note" role="status" ${v.width>OVERVIEW_WIDTH?'':'hidden'}>Large one-line (${g.items.length} items). Zoomed out, it shows lines and symbols only. Zoom in, use Find, or select an item and press Focus to read labels and currents.</p>`})()}<div class="canvas ${placementKind?'placing':drawingConnection?'connecting':''}">${canvas()}${diagramMenu?diagramMenuMarkup():''}</div><div class="diagram-legend"><span><i class="legend-bus"></i> Bus fault level</span><span><i class="legend-fault"></i> Selected fault</span><span><i class="legend-open"></i> Open connection</span></div><div class="canvas-foot"><span>Double-click equipment or cables for properties · drag empty space to pan · Ctrl + scroll to zoom · Delete removes selected equipment · arrow keys move · Ctrl+Z undo · Ctrl+Y redo · Esc deselects</span><span>${hasBranchCurrents(project)?'Branch RMS: From / To sides for selected fault.':'Branch RMS requires a 3-phase study.'}</span></div></section>`;
}
function drawingSelectionSummary(){
 if(selection==='settings')return editor();
 const item=itemById(selection);
 if(!item)return '<section class="editor drawing-summary"><div class="drawing-summary-body"><span class="eyebrow">DRAW & EDIT</span><h3>Build on the single-line</h3><p>Choose equipment from the palette and place it on the drawing.</p><p><strong>Double-click</strong> any equipment or cable to open its properties.</p><p><strong>Drag bus ends</strong> to change their length. Drag the middle to move the bus.</p><button data-select="settings">Study setup</button></div></section>';
 const bus=project.buses.includes(item),link=project.branches.find(b=>b.id===item.linkId),connection=link||item,busName=id=>project.buses.find(b=>b.id===id)?.name||'Disconnected',issues=pending?[]:calculation.issues.filter(i=>i.id===item.id);
 const connections=item.kind==='pv-array'?(project.sources.find(s=>s.id===item.inverterId)?.name||'Standalone PV reference'):bus?`${project.sources.filter(s=>s.bus===item.id).length+project.branches.filter(b=>b.from===item.id||b.to===item.id).length+project.devices.filter(d=>d.bus===item.id).length} attached items`:connection.from!==undefined?`${busName(connection.from)} → ${busName(connection.to)}`:busName(item.bus);
 return `<section class="editor drawing-summary"><div class="editor-head"><div><span class="eyebrow">${esc(names[item.equipmentType||item.kind]||'Bus')}</span><h3>${esc(item.name)}</h3></div><button class="icon-button" data-action="close-editor" aria-label="Clear selection">×</button></div><div class="drawing-summary-body"><button class="primary" data-edit-equipment="${esc(item.id)}">Open properties</button><p>Double-click the ${bus?'bus':'symbol or connection line'} to edit its values.</p><dl><dt>Connection</dt><dd>${esc(connections)}</dd><dt>${item.kind==='pv-array'?'Array reference Voc':bus?'Nominal voltage':'Operating voltage'}</dt><dd>${esc(voltage(item.kind==='pv-array'?pvArraySummary(item).vocV:bus?item.voltage:project.buses.find(b=>b.id===(item.bus||item.to))?.voltage||item.voltage))}</dd>${item.kind==='cable'?`<dt>Selected cable</dt><dd>${esc([item.material,item.size].filter(Boolean).join(' · ')||'Choose cable in properties')}</dd><dt>R1 / X1 · Ω/kft</dt><dd>${n(item.rPerM==null?null:item.rPerM*304.8,5)} / ${n(item.xPerM==null?null:item.xPerM*304.8,5)}</dd>`:''}</dl>${bus?'<p class="bus-resize-tip">Drag either end handle to stretch or shorten this bus. Drag the middle to move it.</p>':''}${issues.map(i=>`<div class="inline-issue ${i.severity==='warning'?'warning':''}">${esc(i.message)}</div>`).join('')}<button data-select="settings">Study setup</button></div></section>`;
}
function networkView(){return workspaceMarkup({diagram:diagramPanel(true),editor:equipmentEdit?'<section class="editor drawing-summary"><div class="drawing-summary-body"><h3>Equipment data is open</h3><p>Save or cancel the popup to continue drawing.</p></div></section>':selection==='review'?`<section class="editor"><div class="editor-scroll">${reviewView()}</div></section>`:selection?editor():drawingSelectionSummary(),placement:placementKind,connecting:drawingConnection,repeat:repeatPlacement,editAfterPlace})}

function listView(){const groups=[['Sources',project.sources],['Transformers & feeders',project.branches.filter(x=>x.kind!=='link')],['Equipment',project.devices],['Connection buses',project.buses]];return `<section class="equipment-rail"><div class="rail-heading"><span class="eyebrow">YOUR LINEUP</span><h2>Equipment</h2><button class="primary" data-action="add-menu">+ Add equipment</button><button data-action="connect-buses" ${project.buses.length<2?'disabled':''}>Connect existing buses</button></div>${groups.filter(([,items])=>items.length).map(([label,items])=>`<section class="equipment-group"><h3>${label}<span>${items.length}</span></h3>${items.map(x=>{const bs=project.buses.find(b=>b.id===(x.bus||x.to)),a=project.buses.find(b=>b.id===x.from),issues=pending?[]:calculation.issues.filter(i=>i.id===x.id),bad=issues.some(i=>i.severity==='error');return `<button class="equipment-item ${selection===x.id?'chosen':''}" data-select="${x.id}" aria-pressed="${selection===x.id}"><span class="item-mark ${bad?'item-error':''}">${project.buses.includes(x)?'●':x.kind==='transformer'?'◉':x.kind==='cable'?'⇄':'ϟ'}</span><span><strong>${esc(x.name)}</strong><small>${esc(names[x.equipmentType||x.kind]||'Bus')} · ${x.enabled===false?'Out of service':x.voltage?voltage(x.voltage):bs?.voltage?voltage(bs.voltage):'Voltage needed'}</small><small class="item-connection">${a?esc(a.name)+' → ':''}${esc(bs?.name||project.buses.includes(x)&&'Connection point'||'Choose connection')}</small></span>${bad?'<b class="rail-error" aria-label="Input required">!</b>':''}</button>`}).join('')}</section>`).join('')||'<p class="rail-empty">Start with a utility or connection bus. Add only the items in your actual system.</p>'}</section>`}
function dlgCurrentView(r){
 if(!r||r.totalA===null)return `<div class="result-empty">${esc(r?.faultNote||'Complete the network inputs and equivalent R2/X2/R0/X0 at this bus.')}</div>`;
 return `<div class="math-grid"><div>Phase A RMS<strong>${ka(r.phaseRMSA.a)}</strong></div><div>Phase B RMS<strong>${ka(r.phaseRMSA.b)}</strong></div><div>Phase C RMS<strong>${ka(r.phaseRMSA.c)}</strong></div><div>Maximum phase RMS<strong>${ka(r.totalA)}</strong></div><div>Ground return RMS<strong>${ka(r.groundA)}</strong></div></div><p class="micro">B–C–ground, ABC phase rotation. B and C are joined through one common impedance to ground. Equipment RMS checks use the largest phase current; ground return is |Ib + Ic| = |3I0|. Z2 and Z0 must be equivalent sequence data for this bus and operating case.</p>`;
}
function contributionView(r){if(isExtendedStudy(project))return analysisCurrentMarkup(project,r);if(project.settings.faultType==='dlg')return dlgCurrentView(r);if(!hasBranchCurrents(project))return '<p>Per-source and branch-current details are available for three-phase studies. Unbalanced results use equivalent sequence data at each bus.</p>';if(!r||r.totalA===null)return `<div class="result-empty">${esc(r?.faultNote||(r?.status?.startsWith('DISCONNECTED')?'No active source reaches this bus. Check the Connected bus and From/To assignments.':'Complete the network inputs to calculate this location.'))}</div>`;const max=Math.max(...(r.details||[]).map(d=>d.amps),1);return `<div class="category-totals">${[['utility','Utility'],['pv','PV'],['bess','BESS'],['generator','Generator'],['other','Other / motor']].map(([k,l])=>`<div><span>${l}</span><strong>${ka((r.groups?.[k]||0)+(k==='other'?(r.groups?.motor||0)+(r.groups?.otherSource||0):0))}</strong></div>`).join('')}</div><p class="micro">Category values are sums of source magnitudes. The total uses source phasors, with unknown inverter phases added as a screening bound.</p><div class="contributions">${(r.details||[]).map(d=>`<div class="contribution"><div><strong>${esc(d.name)}</strong><span>${esc(names[d.kind])}${d.expired?' · duration elapsed':''}</span></div><div class="track"><i style="width:${Math.min(100,d.amps/max*100)}%"></i></div><b>${ka(d.amps)}</b></div>`).join('')}</div>`}
function mathView(r){if(isExtendedStudy(project))return analysisResultsMarkup(project,calculation.results);return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">CALCULATION DETAILS</span><h2>${esc(r?.busName||'Select a fault bus')}</h2></div></div>${!r||r.totalA===null?`<p>${esc(r?.faultNote||'Complete the input review first.')}</p>`:`<div class="math-intro">${isSinglePhase(project)?`Full-voltage two-wire nodal solution. Current base = S / V; transformer leakage = V² / full nameplate VA × %Z. Cable impedance includes the complete outgoing and return loop. Fault current = |Eloop / (Zloop + Zfault)|.`:project.settings.faultType==='3phase'?`Balanced nodal admittance solution on ${n(project.settings.baseMVA)} MVA with each bus’s nominal voltage base. Voltage sources are Norton equivalents; transformers use ratio, phase shift and leakage impedance. Contributions use the same passive network.`:`Equivalent sequence calculation at this bus. Z1 comes from the positive-sequence nodal model; Z2 and Z0 use the entered bus equivalents${project.settings.assumeZ2?' or the explicitly selected Z2 = Z1 screen':''}. ${project.settings.faultType==='ll'?'Line current = √3 × |E| / |Z1 + Z2 + Zfault|.':project.settings.faultType==='dlg'?'I1 = E / [Z1 + Z2 × (Z0 + 3Zfault) / (Z2 + Z0 + 3Zfault)]. I2 = −I1 × (Z0 + 3Zfault) / (Z2 + Z0 + 3Zfault); I0 = −I1 × Z2 / (Z2 + Z0 + 3Zfault). Transform sequence currents to ABC phases; reported RMS is max(|Ib|, |Ic|).':'Line current = 3 × |E| / |Z1 + Z2 + Z0 + 3 × Zfault|.'}`}</div><div class="math-grid"><div>Bus voltage<strong>${voltage(r.voltage)}</strong></div><div>Thevenin impedance<strong>${z(r.zth)}</strong></div><div>${project.settings.faultType==='dlg'?'Maximum phase RMS':'Total '+(r.bound?'magnitude bound':'phasor RMS')}<strong>${ka(r.totalA)}</strong></div><div>Effective X/R<strong>${r.xr===Infinity?'∞':n(r.xr)}</strong></div><div>Asymmetrical RMS screening at study time<strong>${ka(r.asymA)}</strong></div><div>Peak screening<strong>${ka(r.peakA)}</strong></div></div>${r.sequence?`<div class="math-grid"><div>Positive sequence Z1<strong>${z(r.sequence.z1)}</strong></div><div>Negative sequence Z2<strong>${z(r.sequence.z2)}</strong></div><div>Zero sequence Z0<strong>${project.settings.faultType==='ll'?'Not used for LL':z(r.sequence.z0)}</strong></div><div>Prefault phase voltage |E|<strong>${n(abs(r.sequence.referenceVoltage))} V</strong></div></div>`:''}${(hasBranchCurrents(project)?r.details:[]).map(d=>`<details class="math-source" open><summary>${esc(d.name)} <strong>${ka(d.amps)}</strong></summary><div class="math-grid"><div>Source terminal fault level<strong>${ka(d.terminalA)}</strong></div><div>Source impedance at terminal<strong>${z(d.sourceImpedance)}</strong></div><div>Source impedance referred to fault voltage<strong>${z(d.sourceImpedanceAtFault)}</strong></div><div>Calculated fault contribution<strong>${ka(d.amps)}</strong></div><div>Diagnostic series-path impedance at fault voltage<strong>${z(d.pathSeriesZ)}</strong></div></div>${d.current?`<div class="model-note">Manufacturer-limited current injection. ${d.unknownAngle?'Phase unknown: added as a magnitude bound.':'Known current phase used.'} ${d.expired?'Contribution removed after supplied duration.':''} Transformer/cable impedances are in the network; current divides among the fault path and suppressed conventional source admittances. Pure series impedance does not reduce an ideal regulated current.</div>`:''}<table><thead><tr><th>Path element</th><th>Impedance at element's To side</th><th>Voltage base</th><th>Referred to fault voltage</th></tr></thead><tbody>${d.path.map(e=>`<tr><td>${esc(e.name)} · ${esc(e.kind)}</td><td>${z(e.ohms)}</td><td>${voltage(e.atVoltage)}</td><td>${z({r:e.ohms.r*(r.voltage/e.atVoltage)**2,i:e.ohms.i*(r.voltage/e.atVoltage)**2})}</td></tr>`).join('')||'<tr><td colspan="3">Source is at the fault bus.</td></tr>'}</tbody></table>${d.meshed?'<p class="micro">This is one diagnostic path through a meshed network. The solver uses every connected branch; the table is not an independent series-path sum.</p>':''}<details><summary>Branch current from this source during the fault</summary><table><tbody>${d.branchFlows.map(e=>`<tr><td>${esc(e.name)}</td><td>From: ${ka(e.amps)}</td><td>To: ${ka(e.toAmps)}</td></tr>`).join('')}</tbody></table></details></details>`).join('')}`}</section>`}
function resultsView(){if(pending)return '<section class="panel"><h2>Updating network results…</h2><p>Calculate the system to see results for the current inputs.</p></section>';const r=result();if(isExtendedStudy(project))return analysisResultsMarkup(project,calculation.results);return `<div class="results-grid">${contributionPanel(r)}${allBusPanel()}</div>${mathView(r)}${branchView(r)}${dutyView()}${databaseScreensView()}`}
function contributionPanel(r){return `<section class="panel"><div class="panel-heading"><h2>${project.settings.faultType==='dlg'?'Phase and ground currents':'Contribution at selected bus'}</h2>${badge(r?.status||'No result')}</div>${contributionView(r)}<div class="result-note">${isSinglePhase(project)?singlePhaseScope:project.settings.faultType!=='3phase'?'Unbalanced faults use equivalent sequence data at the fault bus. Source and branch decomposition is available for three-phase studies.':r?.bound?'Unknown inverter phase: conservative magnitude-sum bound; category magnitudes are not an exact phasor total.':'Source phasors are combined at the selected fault location, after solving all impedances and transformer ratios.'}</div></section>`}
function allBusPanel(){return `<section class="panel"><h2>All bus fault levels</h2><div class="table-scroll"><table><thead><tr><th>Fault location</th><th>Voltage</th><th>${project.settings.faultType==='dlg'?'Maximum phase RMS':'RMS fault'}</th>${project.settings.faultType==='dlg'?'<th>Ground return RMS</th>':''}<th>Status</th></tr></thead><tbody>${project.buses.map(b=>{const q=result(b.id);return `<tr><td><button class="text-button" data-fault-bus="${b.id}">${esc(b.name)}</button></td><td>${voltage(b.voltage)}</td><td>${pending?'Updating…':ka(q?.totalA)}</td>${project.settings.faultType==='dlg'?`<td>${ka(q?.groundA)}</td>`:''}<td>${badge(q?.status||'Not calculated')}</td></tr>`}).join('')}</tbody></table></div></section>`}
function reportResultsView(){
 if(pending)return resultsView();
 if(isExtendedStudy(project))return reportHas('buses')||reportHas('sources')||reportHas('branches')?part('buses sources branches',analysisResultsMarkup(project,calculation.results)):'';
 const r=result(),grid=(reportHas('sources')?part('sources',contributionPanel(r)):'')+(reportHas('buses')?part('buses',allBusPanel()):'');
 return (grid?`<div class="results-grid">${grid}</div>`:'')+(reportHas('buses')?part('buses',mathView(r)):'')+(reportHas('branches')?part('branches',branchView(r)):'')+(reportHas('duty')?part('duty',dutyView()):'')+(reportHas('screens')?part('screens',databaseScreensView()):'');
}
// A report part can be removed from the page without rebuilding the rest of a large report.
function part(keys,html){return html?`<div class="report-part" data-report-part="${keys}">${html}</div>`:'';}
function reportAvailable(){const a=new Set(SECTION_KEYS);if(!(project.pvArrays||[]).length)a.delete('pv');if(isExtendedStudy(project)){a.delete('methodology');}return a;}
function reportContentsPanel(){return reportChoiceMarkup(reportChoice(),{project,studies:reportStudies(),available:reportAvailable()});}
function reportExtraStudies(){const chosen=new Set(reportChoice().studies);let html='';for(const s of reportStudies()){if(!chosen.has(s.key)||!s.ready)continue;try{for(const sheet of s.sheets())html+=sheetTableMarkup(sheet);}catch(e){html+=`<section class="panel"><h2>${esc(s.label)}</h2><p>Not included: ${esc(e.message)}</p></section>`;}}return html;}
function reportPvView(){return reportHas('pv')&&!reportHas('inputs')&&(project.pvArrays||[]).length?`<section class="panel"><h2>PV array data</h2>${project.pvArrays.map(a=>`<h3>${esc(a.name)}</h3>${pvArraySummaryMarkup(a)}`).join('')}</section>`:'';}
function branchView(r){
 if(!hasBranchCurrents(project)||!r||r.totalA===null)return '';
 const busName=new Map(project.buses.map(b=>[b.id,b.name]));
 return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">CURRENT THROUGH THE NETWORK</span><h2>Branch currents · fault at ${esc(r.busName)}</h2></div></div><div class="table-scroll"><table><thead><tr><th>Connection</th><th>From bus</th><th>From-side RMS</th><th>To bus</th><th>To-side RMS</th><th>Basis</th></tr></thead><tbody>${(r.branchFlows||[]).map(e=>`<tr><td><button class="text-button" data-select="${e.id}">${esc(e.name)}</button></td><td>${esc(busName.get(e.from)||'—')}</td><td>${ka(e.fromA)}</td><td>${esc(busName.get(e.to)||'—')}</td><td>${ka(e.toA)}</td><td>${e.bound?'Magnitude bound':'Phasor RMS'}</td></tr>`).join('')||'<tr><td colspan="6">No separate branch at this location.</td></tr>'}</tbody></table></div><p class="micro">Terminal phasors point into each branch. Transformer currents use each winding’s voltage base; cable and switch currents are equal and opposite. Unknown inverter phases give a stated magnitude bound.</p>${r.outputScope==='compact'?`<p class="micro">Large network (${project.buses.length} buses): the selected fault bus lists every branch. For the other buses the stored table keeps the connections at the faulted bus, the nearest protective devices and every branch’s worst-case fault, which is what the equipment and cable duty checks use. Select a bus to see its full table.</p>`:''}</section>`;
}
function dutyView(){return `<section class="panel"><h2>Equipment rating checks</h2><div class="table-scroll"><table><thead><tr><th>Equipment / bus</th><th>Assembly SCCR</th><th>Interrupting RMS</th><th>Check</th></tr></thead><tbody>${project.devices.filter(d=>d.enabled!==false).map(d=>{const q=result(d.bus),duty=deviceDuty(d,q,project,calculation.results);return `<tr><td><button class="text-button" data-select="${d.id}">${esc(d.name)}</button><small>${esc(project.buses.find(b=>b.id===d.bus)?.name||'Disconnected')}</small></td><td>${ka(duty.sccrDutyA)} / ${ka(d.sccrA)}<small>Available bus RMS / entered SCCR</small></td><td>${ka(duty.interruptDutyA)} / ${ka(d.interruptA)}<small>${esc(duty.basis||'Calculation required')}${d.linkId&&duty.interruptBusId?' · fault at '+esc(project.buses.find(b=>b.id===duty.interruptBusId)?.name||'—'):''}</small></td><td>${badge(duty.status)}${duty.failedType?'<small>'+esc(duty.failedType)+' rating exceeded</small>':''}</td></tr>`}).join('')||'<tr><td colspan="4">Add equipment ratings at the locations you want to check.</td></tr>'}</tbody></table></div><p class="micro">SCCR uses the available RMS at the assembly bus. With a separate equipment connection, interrupting RMS checks the largest through-connection current across calculated bus faults in this scenario. Equipment without a separate connection uses a bus RMS screen. Peak is a bus screen; branch-specific peak and contact timing require further review.</p></section>`}
function reviewView(){if(pending)return `<section id="input-review" class="panel"><h2>Input review & engineering assumptions</h2><p>${running?'Checking the current network…':'Inputs have changed. Calculate to check the current network.'}</p></section>`;return `<section id="input-review" class="panel"><h2>Input review & engineering assumptions</h2>${calculation.issues.length?calculation.issues.map(i=>`<div class="review-row ${i.severity}"><span>${i.severity==='error'?'Fix input':i.severity==='info'?'Unused item':'Assumption'}</span><p>${esc(i.message)}</p><button data-select="${i.id}">Open item</button></div>`).join(''):'<p>No missing or inconsistent inputs detected. Review the stated model assumptions before using equipment-duty results.</p>'}${project.notes.map(t=>`<div class="model-note">${esc(t)}</div>`).join('')}</section>`}
function settingsView(){const s={...project.settings,id:'settings'},inactiveTime=isDcStudy(project)||isSplitPhaseFault(project),timeError=(project.inputErrors||[]).some(e=>e.id==='settings'&&e.key==='time');return `<section id="study-controls" class="panel"><h2>Study controls</h2><p>Set the fault type, operating case and calculation assumptions for this study.</p>${isSinglePhase(project)?'<p class="model-note">'+singlePhaseScope+'</p>':''}<div class="form-grid">${input(s,'frequency','System frequency (Hz)',{required:true})+input(s,'scenario','Operating scenario',{options:[['base','Normal / base'],['maximum','Maximum'],['minimum','Minimum']]})+input(s,'voltageFactor','Prefault voltage factor (pu)',{help:'Engineering prefault factor; not a full IEC correction-factor implementation.'})+input(s,'faultType','Fault type',{options:analysisFaultTypes})+(!inactiveTime||timeError?input(s,'time',inactiveTime?'Retained study time (seconds)':'Study time after fault (seconds)',{help:inactiveTime?'This model does not use time. Correct the incomplete stored number to resolve its input error.':'Used for inverter contribution duration and DC-offset screening.'}):'')+(inactiveTime?'':input(s,'generatorStage','Generator reactance stage',{options:[['initial','Initial · Xd″'],['transient','Transient · Xd′'],['steady','Steady state · Xd']]}))+input(s,'faultR',s.faultType==='dlg'?'Common ground resistance (Ω)':'Fault resistance (Ω)',{help:s.faultType==='dlg'?(usesConnectedSequences(project)?'B and C are joined through one common ground impedance. Enter the explicit equipment sequence paths in their properties.':'B and C are bolted together, then connected to ground through this one impedance. Enter equivalent R0/X0 in each bus property popup.'):s.faultType==='ll'?'Impedance between the two faulted phases.':'Fault-path resistance.'})+input(s,'faultX',s.faultType==='dlg'?'Common ground reactance (Ω)':'Fault reactance (Ω)',{help:s.faultType==='dlg'?'Reactance of the same common path to ground; it is not a separate impedance in each phase.':'Fault-path reactance.'})+input(s,'baseMVA','Calculation base MVA',{required:true,help:'Changing this base should not change physical results.'})+(isExtendedStudy(project)?'':input(s,'assumeZ2','Explicit unbalanced screening assumption: Z2 = Z1',{type:'checkbox',help:'Covers the negative sequence only. SLG and DLG still need each bus’s zero-sequence R0 and X0, which include the actual grounding path.'}))+input(s,'auto','Automatically recalculate edits',{type:'checkbox'})+analysisSettingsFields(project,input)}</div>${isExtendedStudy(project)?'<p class="model-note">'+esc(analysisScope(project))+'</p><button data-action="example-model">Load an illustrative worked example of this model</button>':''}</section>`}
let manifestRequest=null;
async function loadManifest(){if(databaseManifest)return databaseManifest;if(manifestRequest)return manifestRequest;manifestRequest=(async()=>{const response=await fetch('database/manifest.json',{cache:'no-cache'});if(!response.ok)throw Error('Could not load the equipment catalog');const data=await response.json();if(!data?.sheets||typeof data.sheets!=='object'||Array.isArray(data.sheets)||Object.values(data.sheets).some(meta=>!meta||!Number.isInteger(meta.count)||meta.count<0||typeof meta.file!=='string'||!/^database\/[a-z0-9_-]+\.json$/.test(meta.file)))throw Error('Unexpected equipment catalog contents');databaseManifest=data;return data})();try{return await manifestRequest}finally{manifestRequest=null}}
async function loadDB(sheet,{full=false}={}){const cached=loadedDB.get(sheet);if(cached&&(!full||cached.fullWorkbook||!cached.compact&&!databaseManifest?.workbookSheets?.[sheet]))return cached;if(!databaseManifest)await loadManifest();if(full&&databaseManifest.workbookSheets?.[sheet]){const d=await loadWorkbookSheet(sheet);loadedDB.set(sheet,d);return d;}const meta=databaseManifest.sheets[sheet];if(!meta)throw Error('Database category unavailable');const compact=sheet==='CABLES'&&!full?databaseManifest.cablePicker:null;if(compact&&(compact.schema!==1||!/^database\/[a-z0-9_-]+\.json$/.test(compact.file)))throw Error('Unexpected cable library declaration');const response=await fetch(compact?.file||meta.file,{cache:'no-cache'});if(!response.ok)throw Error('Could not load '+sheet);const payload=await response.json(),d=compact?decodeCableLibrary(payload):payload;if(d.sheet!==sheet||!Array.isArray(d.records))throw Error('Unexpected database contents for '+sheet);if(compact&&d.records.length!==compact.count)throw Error('Incomplete cable library download');if(!loadedDB.get(sheet)?.fullWorkbook&&(!compact||!loadedDB.get(sheet)||loadedDB.get(sheet).compact))loadedDB.set(sheet,d);return loadedDB.get(sheet)}
async function refreshDB(){const sheet=dbSheet,target=dbTarget,request=++dbRequest;dbRows=null;dbError='';render();try{const rows=await loadDB(sheet,{full:true});if(request!==dbRequest||target!==dbTarget||sheet!==dbSheet)return;dbRows=rows;render()}catch(error){if(request!==dbRequest||target!==dbTarget||sheet!==dbSheet)return;dbError=String(error.message);render()}}
const compatibleDB=catalogCategories;
function dbValue(k,v){const units={voltage:'V',v1:'V',v2:'V',ratedVoltage:'V',power:'VA',faultMVA:'MVA',faultA:'A',peakA:'A',interruptA:'A',sccrA:'A',rPerM:'Ω/m',xPerM:'Ω/m',r0PerM:'Ω/m',x0PerM:'Ω/m',zPercent:'%',frequency:'Hz',duration:'s',xr:'X/R',multiplier:'pu'};const labels={v1:'Primary',v2:'Secondary',power:'Rating',faultMVA:'Short-circuit MVA',faultA:'Fault RMS',peakA:'Peak',interruptA:'Interrupting',sccrA:'SCCR',rPerM:'R1',xPerM:'X1',r0PerM:'R0',x0PerM:'X0',ratedVoltage:'Rated voltage',zPercent:'Impedance',frequency:'Frequency',voltage:'Voltage',xr:'X/R',duration:'Duration',multiplier:'Fault multiplier'};let val=typeof v==='number'?n(v,6):esc(v);if(['voltage','v1','v2','ratedVoltage'].includes(k))val=voltage(v);else if(['faultA','peakA','interruptA','sccrA'].includes(k))val=ka(v);else if(k==='power')val=n(v/1000)+' kVA';else if(units[k])val+=' '+units[k];return `<span class="db-value"><b>${esc(labels[k]||k)}</b> ${val}</span>`}
function databaseView(){const item=itemById(dbTarget),cats=Object.entries(databaseManifest?.sheets||{}).filter(([sheet,m])=>(compatibleDB[item?.kind]||[]).includes(sheet)&&m.count>0),rows=dbRows?.records||[],filtered=filterCatalog(dbSheet,rows,item,project,{...dbFilters,search:dbSearch}),page=filtered.slice(dbPage*25,(dbPage+1)*25),selectFilter=(key,label,values)=>`<label>${label}<select data-db-filter="${key}"><option value="">All ${label.toLowerCase()}</option>${[...new Set(values.filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${dbFilters[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;return `<section class="panel"><div class="panel-heading"><div><span class="eyebrow">MASTER DATABASE · FAULT STUDY RECORDS</span><h2>Choose ${esc(names[item?.kind]||'equipment')} data</h2><p>Populate ${esc(item?.name)}. Existing bus voltages stay unchanged; missing data stays editable.</p>${item?.kind==='cable'?`<p class="db-voltage-context">Connected buses: From ${esc(voltageLabel(project.buses.find(b=>b.id===item.from)?.voltage))} → To ${esc(voltageLabel(project.buses.find(b=>b.id===item.to)?.voltage))}. Cable insulation rating must cover the operating voltage.</p>`:''}</div></div><div class="db-controls"><select id="db-category" aria-label="Database category">${cats.map(([sheet,m])=>`<option value="${sheet}" ${sheet===dbSheet?'selected':''}>${esc(sheet.replaceAll('_',' '))} · ${(databaseManifest.workbookSheets?.[sheet]?.count??m.count).toLocaleString()}</option>`).join('')}</select><input id="db-search" type="search" value="${esc(dbSearch)}" placeholder="Search model, manufacturer, conductor size…" aria-label="Search master database"></div><div class="db-filters">${selectFilter('manufacturer','Manufacturer',rows.map(r=>catalogRecord(dbSheet,r).manufacturer))}${item?.kind==='cable'?selectFilter('material','Material',rows.map(r=>catalogRecord(dbSheet,r).values.material))+selectFilter('size','Size',rows.map(r=>catalogRecord(dbSheet,r).values.size)):''}<label class="db-fit"><input type="checkbox" data-db-filter="fitOnly" ${dbFilters.fitOnly?'checked':''}>Match connected voltage & study frequency</label></div><div class="db-count">${dbError?'Records unavailable':dbRows?filtered.length.toLocaleString()+' matching records · page '+(dbPage+1):'Loading useful equipment records…'}</div>${dbError?`<div class="inline-issue" role="alert">${esc(dbError)} <button data-action="retry-db">Retry loading records</button></div>`:''}${dbInspect?`<details class="raw-record" open><summary>Original database values · row ${dbInspect._row}</summary><pre>${esc(JSON.stringify(dbInspect,null,2))}</pre></details>`:''}<div class="table-scroll"><table><thead><tr><th>Record / model</th><th>Useful electrical data</th><th>Source / verification</th><th>Selection</th></tr></thead><tbody>${page.map(row=>{const mapped=catalogRecord(dbSheet,row),reasons=recordCompatibility(dbSheet,row,item,project),voltageIssue=item?.kind==='cable'?cableVoltageMessage(project,{...item,ratedVoltage:mapped.values.ratedVoltage}):null,values=Object.entries(mapped.values).filter(([,v])=>v!==null&&v!==''&&v!==undefined&&typeof v!=='boolean').slice(0,9);return `<tr><td><strong>${esc(recordName(row))}</strong>${reasons.length?`<small class="text-warning">${esc(reasons.join('. '))}</small>`:''}</td><td>${values.map(([k,v])=>dbValue(k,v)).join('')}</td><td>${esc(mapped.db.status||'Not supplied')}<small>${esc(mapped.db.notes.slice(0,160))}</small></td><td><button data-apply-db="${row._row}" class="primary" ${voltageIssue?`disabled title="${esc(voltageIssue)}"`:""}>Use record</button><button data-inspect-db="${row._row}">Source data</button></td></tr>`}).join('')||'<tr><td colspan="4">No matching records. Adjust filters, or enter documented values manually.</td></tr>'}</tbody></table></div><div class="actions"><button data-db-prev ${dbPage===0?'disabled':''}>← Previous</button><button data-db-next ${(dbPage+1)*25>=filtered.length?'disabled':''}>Next →</button><button data-action="cancel-db">Enter manually / close</button></div><p class="micro">Only records relevant to this calculation are included. Ratings are taken from their stated source; manufacturer applicability and missing properties remain visible.</p></section>`}
function folderView(){
 const f=folder.state,linked=f.linkedFile&&folderProjectId===project.id?f.linkedFile:null,size=n=>n>=1e6?(n/1e6).toFixed(1)+' MB':Math.max(1,Math.round(n/1e3))+' kB';
 if(!f.supported)return `<section class="panel folder-panel"><span class="eyebrow">PROJECT FOLDER</span><h2>Projects on your computer</h2><p>This browser cannot connect to a folder. Use Chrome or Edge on a desktop computer to keep projects as files in a folder of your choice, or use Export project JSON and Import project JSON below.</p></section>`;
 const head=`<span class="eyebrow">PROJECT FOLDER</span><h2>Projects on your computer</h2>`;
 if(!f.handle)return `<section class="panel folder-panel">${head}<p>Choose a folder on this computer for your project files. Each project is saved there as a file you can open, update, rename or delete. Nothing is uploaded.</p><div class="actions"><button class="primary" data-action="folder-connect">Connect project folder</button></div>${f.message?`<p class="micro" role="status">${esc(f.message)}</p>`:''}</section>`;
 if(f.permission!=='granted')return `<section class="panel folder-panel">${head}<p>Folder <strong>${esc(f.folderName)}</strong> needs your permission again before the Studio can read or save files.</p><div class="actions"><button class="primary" data-action="folder-reconnect">Allow access to ${esc(f.folderName)}</button><button data-action="folder-disconnect">Disconnect</button></div>${f.message?`<p class="micro" role="status">${esc(f.message)}</p>`:''}</section>`;
 const rows=f.files.map(x=>`<div class="saved-row"><div><strong>${esc(x.name)}</strong><small>${esc(new Date(x.modified).toLocaleString())} · ${size(x.size)}${x.name===linked?' · open now':''}</small></div><div class="actions"><button data-folder-open="${esc(x.name)}">Open</button><button data-folder-delete="${esc(x.name)}">Delete file</button></div></div>`).join('')||'<p>No project files in this folder yet. Save the current project to create one.</p>';
 return `<section class="panel folder-panel">${head}<p>Connected folder: <strong>${esc(f.folderName)}</strong>${linked?` · the open project ${f.autosave?'saves automatically to':'is linked to'} <strong>${esc(linked)}</strong>`:''}.</p><div class="field folder-name-field"><label for="folder-file-name">File name for the current project</label><input id="folder-file-name" value="${esc(linked||projectFileName(project.name))}" autocomplete="off" spellcheck="false"></div><div class="actions"><button class="primary" data-action="folder-save">Save project to folder</button><button data-action="folder-refresh">Refresh list</button>${linked?`<button data-action="folder-autosave" aria-pressed="${f.autosave}">${f.autosave?'Autosave on':'Autosave off'}</button>`:''}<button data-action="folder-disconnect">Disconnect folder</button></div>${f.message?`<p class="micro" role="status">${esc(f.message)}</p>`:''}<h3>Project files</h3>${f.busy&&!f.files.length?'<p>Reading folder…</p>':rows}</section>`;
}
function deviceProjectView(){const saved=read('fault-network-studies-v2',[]),legacy=read('fault-studies-v1',[]);return folderView()+`<section class="panel"><h2>Project details & backups</h2><p>Edit project details in Study setup. Double-click equipment on the single line to edit its values.</p><div class="actions"><button class="primary" data-action="save">Save named study</button><button data-action="export">Export project JSON</button><button data-action="import">Import project JSON</button><button data-action="csv">Export results CSV</button><button data-action="blank">New blank study</button><button data-action="example">Worked example</button></div><p class="micro">${cloudHosted?'These backups are kept on this device. Open one and Save study to keep it across devices.':'Projects and layout positions stay in this browser. Export JSON for a portable backup.'} Earlier version saves remain available.</p></section><section class="panel"><h2>${cloudHosted?'Device backups':'Saved studies'}</h2>${saved.map((s,i)=>`<div class="saved-row"><div><strong>${esc(s.project.name)}</strong><small>${esc(new Date(s.saved).toLocaleString())}</small></div><button data-load-project="${i}">Open</button></div>`).join('')||'<p>No named network studies yet.</p>'}${studyStorage.recoveries().length?'<h3>Stored-data recovery</h3><p>Original JSON is kept here when a stored draft or study list cannot be read.</p>'+studyStorage.recoveries().map((entry,i)=>`<div class="saved-row"><div><strong>${esc(entry.key)}</strong><small>${esc(entry.saved)}</small></div><button data-download-recovery="${i}">Download original JSON</button></div>`).join(''):''}${legacy.length?'<h3>Earlier calculator studies</h3>'+legacy.map((s,i)=>`<div class="saved-row"><div><strong>${esc(s.name)}</strong><small>Workbook model · converted on opening; original retained</small></div><button data-load-legacy="${i}">Convert & open</button></div>`).join(''):''}</section>`}
function projectView(){return (cloudHosted?cloudProjectsView():'')+deviceProjectView()}
// V25 capability benchmark: feature coverage must never be mistaken for standards certification.
// [sector, title, status, current scope, workspace, internal benchmark (not displayed), internal reference URL (not displayed), next gate]
// Benchmark products are kept for the engineering team's comparison work only; the page never shows them.
const atlasAreas=[
 ['Fault current','Connected network fault modelling','bounded','Three-phase, LL, SLG, DLG and connected-sequence faults on meshed and radial networks, source contributions and equipment duty. Sparse solvers handle plant-scale models: a 1,970-bus, 71-source PV plant calculates in seconds; 2,000-bus connected-sequence and split-phase networks calculate in under ten seconds. Each matches its dense solver on the QA networks.','network','ETAP','https://etap.com/packages','Full IEC 60909-0 and ANSI C37 example suites'],
 ['Fault current','IEC 60909 multi-method certification','gap','Peak, transformer and sequence screening exist; the complete IEC 60909 method set (correction factors, machine and inverter rules) is not yet built.','advanced','pandapower','https://pandapower.readthedocs.io/en/latest/shortcircuit.html','Correction factors, machine and inverter-based resource rules, published benchmarks'],
 ['Arc flash','Incident energy and clearing time','bounded','IEEE 1584-2018 incident energy at every bus, clearing time from relay or manufacturer curves with tolerance bands, and the one-line protective device for each bus. Checked against the standard’s Annex D examples and 105,120 published cases.','advanced','EasyPower','https://www.easypower.com/products/easypower','DC arc flash and field-validated device curve sources'],
 ['Protection','Coordination and manufacturer TCC','partial','Relay curves, fuse and LSI trip models, tolerance bands and clearing-time lookup exist. Multi-device selectivity checking is not complete.','operating','SKM','https://skm.com/','Source-revisioned trip units and automatic selectivity across device pairs'],
 ['Cable systems','Conductor sizing and steady-state thermal','bounded','NEC 310 ampacity with corrections, 240.4 protection, 250.122 grounding conductor and I²t short-circuit duty. IEC 60287 is limited to single-core direct-burial cases.','advanced','CYMCAP','https://www.eaton.com/us/en-us/catalog/software/power-cable-ampacity-software.html','Duct banks, grouped trefoils, bonding losses, solar heating and IEC 60853 cycles'],
 ['Cable systems','Cable pulling and cleat forces','gap','Pulling tension, sidewall pressure and short-circuit cleat forces are not built yet.','database','Cableizer','https://www.cableizer.com/','Route geometry, bends, friction and dynamic force models'],
 ['Power flow','AC load flow and contingencies','partial','Balanced load flow with off-nominal transformer taps, checked against an independent π-equivalent oracle. A sparse Newton solver handles plant-scale networks (closed breakers join their buses; the 1,970-bus plant solves in under a second). Balanced N-1 screening and AC time series exist. Unbalanced load flow is not built yet.','operating','DIgSILENT PowerFactory','https://www.digsilent.com/','IEEE test networks, N-1 contingency and unbalanced load flow'],
 ['Power flow','Distribution hosting capacity','gap','Feeder time-series, volt-var and hosting-capacity workflows are not built yet.','operating','OpenDSS','https://opendss.epri.com/IntroductiontoOpenDSS.html','Time-series volt-var, tap controls, unbalance and hosting capacity'],
 ['Power quality','Harmonics and impedance sweeps','partial','Harmonic network screening, IEEE 519 PCC limits and power-factor correction sizing. Frequency sweeps and resonance scans are not complete.','advanced','CYME','https://www.eaton.com/in/en-us/products/utility-grid-solutions/software-modules.html','Frequency-dependent sweeps, resonance and measured harmonic cases'],
 ['Grounding','Grounding grid and touch/step','gap','Grounding references exist; IEEE 80 grid, multilayer soil, touch and step potential are not built yet.','advanced','XGSLab','https://www.easypower.com/products','Soil layers, grid conductors, touch/step and transfer potential'],
 ['Energy storage','BESS and PV DC short circuit','bounded','DC resistive network fault current, independently compared on 120 networks and 525 bus faults. The plant builder creates DC arrays (strings, fuses, combiner boxes, inverter inputs) from your string and cable data.','advanced','EasyPower','https://www.easypower.com/products/easypower','IEC 61660 time-dependent duty and DC arc flash'],
 ['Energy storage','Storage dispatch and optimisation','gap','Year-long dispatch, degradation and capacity sizing are not built yet.','operating','REopt','https://www.nlr.gov/reopt/','8760 dispatch, import/export limits, economics and resilience'],
 ['Solar','PV yield and clipping simulation','partial','PV arrays, inverter fault sources and plant one-lines are modelled. Energy yield, shading and loss simulation are not built yet.','advanced','PVsyst','https://www.pvsyst.com/help/','Weather, bifacial gain, clipping and shading losses'],
 ['Microgrid','Dispatch and dynamic stability','gap','Island transitions, control dynamics and reserve sizing are not built yet.','operating','HOMER Pro','https://homerenergy.com/homer-pro/features','Islanded transitions, reserve and converter behaviour'],
 ['Equipment','Manufacturer catalogue provenance','partial','Curated equipment records with conflict quarantine; not every manufacturer revision and curve has a source sign-off.','database','EasyPower','https://www.easypower.com/products/easypower','Per-record datasheet link, approved revision and nameplate check'],
 ['Project tools','One-line, projects and reporting','partial','Connected one-line that stays responsive at plant scale, a plant builder (AC collector systems, several block types, DC arrays), an equipment table that edits, adds and deletes equipment, project files saved to a folder on your computer, and printed, PDF and Excel reports where you choose which studies are included. Version comparison is not built yet.','projects','ETAP','https://etap.com/packages','Version comparison and audit trail'],
 ['Interoperability','CAD/BIM and utility data import','gap','JSON and spreadsheet transfer exist; IFC, Revit, GIS and CIM utility-model exchange are not built yet.','projects','EasyPower','https://www.easypower.com/products/easypower','CIM utility-model exchange with model reconciliation'],
 ['Engineering QA','Reproducible, traceable study evidence','partial','Independent numerical test suites run on every release (oracle, physics, sequence, DC, arc flash, cable, load flow). Results do not yet carry an input hash and method record.','report','pandapower','https://pandapower.readthedocs.io/','Each result linked to its input hash, method, test evidence and reviewer']
];
function capabilityAtlasMarkup(){
 const total=atlasAreas.length,live=atlasAreas.filter(x=>x[2]==='bounded').length,partial=atlasAreas.filter(x=>x[2]==='partial').length;
 const tags={bounded:'Verified in stated scope',partial:'Partly built',gap:'Not built yet'};
 return `<section class="atlas-page" aria-label="Capability atlas">
 <div class="atlas-hero"><div class="atlas-hero-copy"><span class="atlas-eyebrow">ENGINEERING SYSTEM / V32</span><h2>One workspace.<br><em>Every study accountable.</em></h2><p>The actual scope of this calculator: what is built and tested, what is partly built, and what is still to be built.</p><div class="atlas-hero-actions"><a href="#network" class="atlas-hero-primary">Open single-line studio <span aria-hidden="true">↗</span></a><a href="#projects" class="atlas-hero-link">Study backups</a><button type="button" data-quick-nav="open">Find a tool <kbd>Ctrl K</kbd></button></div></div><div class="atlas-hero-mark" aria-hidden="true"><span>FCS</span><strong>31</strong><small>CAPABILITY ATLAS</small></div></div>
 <div class="atlas-metric-strip" aria-label="Capability coverage"><div><strong>${total}</strong><span>Assessed capabilities</span></div><div><strong>${live}</strong><span>Verified in scope</span></div><div><strong>${partial}</strong><span>Partly built</span></div><div><strong>${total-live-partial}</strong><span>Not built yet</span></div></div>
 <div class="atlas-toolbar"><div><span class="atlas-section-kicker">THE ENGINEERING LIBRARY</span><h3>Capabilities & comparison</h3><p>Search by discipline or capability. All status descriptions refer only to this Studio.</p></div><label for="atlas-search"><span>Search capabilities</span><input id="atlas-search" type="search" placeholder="Try: grounding, IEC 60909, arc flash…" autocomplete="off" spellcheck="false"></label></div>
 <div class="atlas-filters" role="group" aria-label="Filter capability status"><button data-atlas-filter="all" aria-pressed="true">All capabilities</button><button data-atlas-filter="bounded" aria-pressed="false">Verified in scope</button><button data-atlas-filter="partial" aria-pressed="false">Partly built</button><button data-atlas-filter="gap" aria-pressed="false">Not built yet</button><span id="atlas-count" aria-live="polite">${total} of ${total} shown</span></div>
 <div class="atlas-card-grid" id="atlas-cards">${atlasAreas.map(([sector,title,status,scope,href,,,next],index)=>`<article class="atlas-card" data-atlas-status="${status}" data-atlas-text="${esc([sector,title,tags[status],scope,next].join(' ').toLowerCase())}"><div class="atlas-card-head"><span class="atlas-card-number">${String(index+1).padStart(2,'0')} / ${esc(sector)}</span><span class="atlas-chip atlas-${status}">${tags[status]}</span></div><h4>${esc(title)}</h4><p>${esc(scope)}</p><div class="atlas-next"><strong>Next engineering gate</strong><span>${esc(next)}</span></div><div class="atlas-card-links"><a href="#${href}">Open related workspace ↗</a></div></article>`).join('')}</div><p id="atlas-empty" class="atlas-empty" hidden>No matching capabilities. Clear the search or choose another filter.</p>
 <div class="atlas-footer-note"><strong>Engineering release status</strong><p>A model, chart or calculator appearing here does not imply full IEC/IEEE certification, manufacturer approval, legal compliance or suitability for an equipment safety decision. Always verify nameplate inputs, assumptions and standards edition. Private studies are never recovered from a public website without owner-authorised access.</p><a href="#report">Open report workflows ↗</a></div></section>`;
}

function reportInputs(){
 const busName=id=>project.buses.find(b=>b.id===id)?.name||'Disconnected';
 const extras={valueSource:'Value entry mode',userManufacturer:'Manufacturer (user data)',userModel:'Model / part number (user data)',dataReference:'User data source / notes',insulationCustomDesignation:'Custom product insulation marking',temperature:'Impedance-data temperature (°C)',singlePhaseBasis:'Utility two-wire input basis',phaseRating:'Transformer phase/nameplate basis',loopImpedanceBasis:'Cable complete-loop basis',method:'Source data method',angle:'Angle (degrees)',xdpp:'Xd″ (pu)',xdp:'Xd′ (pu)',xd:'Xd (pu)',length:'Length (m)',runs:'Parallel conductors per phase',r:'Resistance (Ω)',x:'Reactance (Ω)',material:'Conductor',size:'Size',cableType:'R/X library / construction',insulationType:'Installed insulation designation',insulationLocation:'Installation location',insulationProductTemp:'Insulation temperature from product marking (°C)',cableCategory:'Cable type filter',shift:'Phase shift (degrees)',primaryConnection:'Primary winding',secondaryConnection:'Secondary winding',grounding:'Grounding',neutralR:'Neutral R (Ω)',neutralX:'Neutral X (Ω)',maxInclude:'Maximum case included',minInclude:'Minimum case included',maxStrength:'Maximum strength',minStrength:'Minimum strength'};
 Object.assign(extras,Object.fromEntries(pvArrayFields.map(([k,l,u])=>[k,l+(u?' ('+u+')':'')])) ,{modulesPerString:'Modules in series per string',parallelStrings:'Strings in parallel'});
 const keys=[...pvArrayFields.map(f=>f[0]),'modulesPerString','parallelStrings','valueSource','userManufacturer','userModel','dataReference','insulationCustomDesignation','temperature','singlePhaseBasis','phaseRating','loopImpedanceBasis','method','voltage','v1','v2','power','faultA','faultMVA','xr','angle','r','x','xdpp','xdp','xd','multiplier','duration','peakA','zPercent','tapPercent','shift','primaryConnection','secondaryConnection','grounding','neutralR','neutralX','length','runs','material','size','cableType','insulationType','insulationLocation','insulationProductTemp','cableCategory','ratedVoltage','interruptA','sccrA','rPerM','xPerM','r0PerM','x0PerM','frequency','maxInclude','minInclude','maxStrength','minStrength'];
 return `<section class="panel report-inputs"><h2>Entered network data</h2><p class="micro">Values below use SI units. ${isExtendedStudy(project)?'All entered values are retained here, including previous-mode references. The selected model uses only its documented model-specific inputs.':"Missing properties are not inferred. Cable R0/X0 and winding/neutral records do not synthesize a sequence network; unbalanced calculations use the equivalent bus sequence data."}</p><div class="table-scroll"><table><thead><tr><th>Item</th><th>Connection / service</th><th>Entered electrical data</th></tr></thead><tbody>${all().map(x=>`<tr><td><strong>${esc(x.name)}</strong><small>${esc(names[x.equipmentType||x.kind]||'Bus')}</small></td><td>${esc(x.kind==='pv-array'?'PV reference → '+(project.sources.find(s=>s.id===x.inverterId)?.name||'None'):x.from?busName(x.from)+' → '+busName(x.to):x.bus?busName(x.bus):'Bus / connection point')}<small>${x.kind==='pv-array'?'Nameplate reference only':x.enabled===false?'Out of service':'In service'}</small></td><td>${keys.filter(k=>x[k]!==null&&x[k]!==undefined&&x[k]!=='').map(k=>singlePhaseInputLabel(project,x,k)?`<span class="db-value"><b>${singlePhaseInputLabel(project,x,k)}</b> ${esc(typeof x[k]==='number'?n(x[k],6):x[k])}${['rPerM','xPerM'].includes(k)?' Ω/m':k==='faultA'?' A':k==='faultMVA'?' MVA':['r','x'].includes(k)?' Ω':''}</span>`:extras[k]?`<span class="db-value"><b>${extras[k]}</b> ${esc(typeof x[k]==='number'?n(x[k],6):typeof x[k]==='boolean'?x[k]?'Yes':'No':x[k])}</span>`:dbValue(k,x[k])).join('')}${x.kind==='pv-array'?pvArraySummaryMarkup(x):''}${analysisInputRows(project,x).map(([label,value,unit])=>`<span class="db-value"><b>${esc(label)}</b> ${esc(typeof value==='object'?JSON.stringify(value):value)} ${esc(unit)}</span>`).join('')}${x.sequence&&!usesConnectedSequences(project)?Object.entries(x.sequence).filter(([,v])=>v!==null&&v!==undefined).map(([k,v])=>`<span class="db-value"><b>Equivalent ${esc(k.toUpperCase())}</b> ${n(v,6)} Ω</span>`).join(''):''}${x.db?`<${x.kind==='cable'?'details':'div'} class="provenance">${x.kind==='cable'?'<summary>'+ (x.db.origin==='manufacturer'?'Manufacturer source and overrides':'Workbook source and overrides')+'</summary>':''}<strong>${esc(x.db.label)}</strong><span>${esc(x.db.sheet)} · row ${esc(x.db.row)} · ${esc(x.db.status||'Status not supplied')}</span><p>${esc(x.db.notes)}</p>${x.db.source.startsWith('https://')?`<a href="${esc(x.db.source)}">Source reference</a>`:esc(x.db.source)}${x.db.overrides?.length?`<small>Manual overrides: ${esc(x.db.overrides.join(', '))}</small>`:''}</div>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function extendedReportView(){return `<div class="report-title"><span class="eyebrow">DOCUMENTED NETWORK FAULT STUDY</span><h1>${esc(project.name)}</h1><p>${esc(project.preparedBy||'Prepared by: not supplied')} · ${esc(project.date)}</p><button class="primary no-print" data-action="print">Print report</button><button class="no-print" data-action="pdf">Download PDF</button><button class="no-print" data-action="xlsx">Download Excel</button></div>${reportContentsPanel()}${reportHas('basis')?`<section class="panel" data-report-part="basis"><h2>Study basis</h2><p>${esc(faultTypeLabel())}</p><p>${esc(analysisScope(project))}</p>${isDcStudy(project)?'<p>Steady-state resistive DC equivalent. No AC RMS/peak or IEC/ANSI duty calculation.</p>':`<p>${esc(project.settings.frequency)} Hz · fault impedance ${z({r:project.settings.faultR,i:project.settings.faultX})}</p>`}</section>`:''}${reportHas('diagram')?`<section class="panel report-diagram" data-report-part="diagram"><h2>System single-line</h2>${canvas()}</section>`:''}${pending?'<section class="panel"><p>Calculate the current inputs before printing results.</p></section>':reportResultsView()}${part('pv',reportPvView())}${reportHas('inputs')?part('inputs',reportInputs()):''}${reportHas('qa')?part('qa',reviewView()):''}${part('studies',reportExtraStudies())}`}
function reportView(){if(isExtendedStudy(project))return extendedReportView();return `<div class="report-title"><span class="eyebrow">CONNECTED-NETWORK FAULT STUDY</span><h1>${esc(project.name)}</h1><p>${esc(project.preparedBy||'Prepared by: not supplied')} · ${esc(project.date)}</p><button class="primary no-print" data-action="print">Print report</button><button class="no-print" data-action="pdf">Download PDF</button><button class="no-print" data-action="xlsx">Download Excel</button></div>${reportContentsPanel()}${reportHas('basis')?`<section class="panel" data-report-part="basis"><h2>Study basis</h2><p>${esc(faultTypeLabel())} · ${esc(project.settings.frequency)} Hz · ${esc(project.settings.scenario)} · ${esc(project.settings.time)} s after fault · prefault factor ${esc(project.settings.voltageFactor)}</p><p>Calculation base: ${n(project.settings.baseMVA)} MVA · Generator stage: ${esc(project.settings.generatorStage)} · ${project.settings.faultType==='dlg'?'Common ground impedance':'Fault impedance'}: ${z({r:project.settings.faultR,i:project.settings.faultX})} · Z2 = Z1 screening: ${project.settings.assumeZ2?'Selected':'Not selected'}</p></section>`:''}${reportHas('diagram')?`<section class="panel report-diagram" data-report-part="diagram"><h2>System single-line</h2>${renderOneLine(project,{results:calculation.results,issues:calculation.issues,pending,selection:null,showCurrents:true})}<p class="micro">${project.settings.faultType==='dlg'?'Bus labels show maximum DLG phase RMS and separate ground return RMS. B and C share the entered common ground impedance.':'Bus values are available fault RMS at each bus. Branch values are From / To currents for the selected fault bus.'}</p></section>`:''}${reportResultsView()}${part('pv',reportPvView())}${reportHas('inputs')?part('inputs',reportInputs()):''}${reportHas('qa')?part('qa',reviewView()):''}${part('studies',reportExtraStudies())}${reportHas('methodology')?`<section class="panel" data-report-part="methodology"><h2>Methodology & limits</h2>${isSinglePhase(project)?'<p>'+singlePhaseScope+' Full-voltage loop current base is S/V; transformer kVA is the full nameplate rating.</p>':''}<p>Complex per-unit nodal admittance solution with voltage sources represented by their Norton equivalents. Transformer ratios and leakage impedances, cable R/X, source strengths and phase angles are included. Source contributions are found by superposition at each fault location. Loops and parallel paths use the full matrix, rather than a single path sum. Generator Xd defines reactance; when X/R is supplied, resistance is X divided by X/R.</p><p>Current-limited inverters use ideal manufacturer-current injections. Without phase data, the total is a magnitude-sum bound. A pure series path does not attenuate an ideal regulated current; actual voltage compliance, controls and sequence behavior require manufacturer data. LL requires valid Z2 or the explicit Z2 = Z1 screen. SLG and DLG require equivalent Z0 that includes the actual grounding path. DLG uses one common B–C–ground impedance and reports maximum phase and ground return RMS separately. Loads, arcing faults, saturation, protection coordination and complete IEC/ANSI correction procedures are outside this model.</p><p>Method: nodal bus-admittance fault study with superposition of source injections. Inverter model limitations: <a href="https://www1.eere.energy.gov/solar/pdfs/distribution_modeling_wkshp2012_behnke.pdf">DOE/NREL/SNL inverter short-circuit characteristics</a>.</p></section>`:''}`}
function drawingCalculationStatus(){
 if(pending)return `<section class="calculation-state compact waiting" role="status"><strong>${running?'Calculating…':'Inputs changed'}</strong><span>${running?'Updating the connected network.':'Calculate to update fault currents.'}</span>${running?'':'<button data-action="calculate">Calculate</button>'}</section>`;
 const errors=calculation.issues.filter(i=>i.severity==='error'),r=result();
 if(errors.length)return `<section class="calculation-state compact blocked" role="alert"><strong>${errors.length} input ${errors.length===1?'issue':'issues'}</strong><span title="${esc(errors[0].message)}">${esc(errors[0].message)}</span>${errors[0].id==='engine'?'<button data-action="calculate">Retry</button>':`<button data-edit-equipment="${esc(errors[0].id)}">Fix input</button>`}<button data-action="review-inputs">All issues</button></section>`;
 if(r?.totalA!=null)return `<section class="calculation-state compact ready" role="status"><strong>${r.status&&r.status!=='CALCULATED'?esc(r.status.charAt(0)+r.status.slice(1).toLowerCase()):'Calculated'}</strong><span>${esc(ka(r.totalA))} at ${esc(r.busName)}${r.status==='SCREENING BOUND'?' · upper bound: inverter fault-current angle unknown':''}</span><a href="#results">View results →</a></section>`;
 const label=!project.buses.length?'Start your drawing':!r||!project.selectedBus?'Choose fault bus':r.status==='DATA REQUIRED'?'Data required':r.status?.startsWith('DISCONNECTED')?'No source reaches this bus':r.status==='NETWORK ERROR'?'Network needs attention':r.status==='INPUT REQUIRED'?'Input required':'Choose fault bus';
 return `<section class="calculation-state compact waiting" role="status"><strong>${label}</strong><span>${esc(r?.faultNote||'Place equipment, connect buses and enter their values.')}</span>${project.buses.length?'<button data-action="choose-fault">Choose bus</button>':''}</section>`;
}
function pvReferenceStatusView(){const issues=pvReferenceIssues(project);return issues.length?`<section class="calculation-state pv-reference-state" role="status"><strong>PV reference data: ${issues.length} ${issues.length===1?'item':'items'} to review</strong><p>Electrical fault results use the source network. Correct these module/array reference values separately.</p>${issues.map(i=>`<p>${esc(i.message)} <button data-edit-equipment="${esc(i.id)}">Edit array</button></p>`).join('')}</section>`:'';}
function calculationStatusView(){if(view==='network')return drawingCalculationStatus();if(pending)return `<section class="calculation-state ${running?'working':'waiting'}" role="status"><strong>${running?'Calculating your connected system…':'Inputs changed — ready to calculate'}</strong><p>${running?'Results will appear here when the calculation finishes.':`Finish editing and press Calculate changes. ${storageOK?'Your entered values are saved on this device.':'Browser storage could not save these inputs. Download study JSON before closing.'}`}</p>${!running?'<button class="primary" data-action="calculate">Calculate changes</button>':''}${!storageOK?'<p>Storage unavailable: export a backup before closing.</p><button data-action="export">Download study JSON</button>':''}</section>`;const errors=calculation.issues.filter(i=>i.severity==='error');if(errors.length){const failed=errors.some(i=>i.id==='engine');return `<section class="calculation-state blocked" role="alert"><h2>${failed?'Calculation could not finish':'Results are blocked by '+errors.length+' input '+(errors.length===1?'issue':'issues')}</h2><p>${failed?(storageOK?'Your inputs are saved. Retry the calculation or download this study for troubleshooting.':'Retry the calculation or download this study. Browser storage could not save these inputs.'):'Correct these items to calculate the current network. Your inputs are retained.'}</p>${errors.slice(0,5).map(i=>`<div class="result-blocker"><span>${esc(i.message)}</span>${i.id!=='engine'?`<button data-select="${esc(i.id)}">Fix input</button>`:''}</div>`).join('')}<div class="actions">${failed?'<button class="primary" data-action="calculate">Retry calculation</button>':'<button data-action="review-inputs">See all input issues</button>'}<button data-action="export">Download study JSON</button></div></section>`}if(!project.buses.length)return '';const r=result();if(r?.totalA!==null&&r?.totalA!==undefined)return '';return `<section class="calculation-state blocked" role="alert"><h2>${esc(r?.status?.startsWith('DISCONNECTED')?'No active source reaches this fault bus':r?.status==='DATA REQUIRED'?'More fault-model data is needed':r?.status==='NETWORK ERROR'?'Network calculation needs attention':'Choose a connected fault bus')}</h2><p>${esc(r?.faultNote||(r?.status?.startsWith('DISCONNECTED')?'Check the Connected bus and From/To assignments, or choose an energized bus in Fault location.':'Select a fault location and review its network inputs.'))}</p><div class="actions"><button data-action="choose-fault">Choose fault location</button>${project.selectedBus?`<button data-select="${project.selectedBus}">Open fault-bus inputs</button>`:''}<button data-action="export">Download study JSON</button></div></section>`}
function inputsView(){const r=result();return `<section class="panel input-intro"><div class="input-intro-heading"><div><span class="eyebrow">ALL INPUTS · ONE WORKSPACE</span><h2>Build the system. See the result.</h2><p>Add only your equipment. Select equipment in the lineup to enter values and change connections.</p></div><div class="workflow-steps"><span>01 Build</span><span>02 Connect</span><span>03 Calculate</span></div></div><div class="form-grid">${input({...project,id:'project'},'name','Project name',{type:'text'})+input({...project,id:'project'},'preparedBy','Prepared by',{type:'text'})+input({...project,id:'project'},'date','Study date',{type:'date'})+input({...project,id:'project'},'caseName','Case / scenario name',{type:'text',help:'Give each saved case a distinct name. Cloud copies keep their own revisions.'})}</div></section><div class="input-workspace"><div class="lineup-column">${listView()}</div>${equipmentEdit?'<section class="editor"><div class="editor-empty"><h3>Equipment properties are open</h3><p>Save or cancel the popup to continue.</p></div></section>':editor()}<aside class="input-context"><section class="panel quick-result"><div class="panel-heading"><div><span class="eyebrow">SELECTED FAULT LOCATION</span><h2>${esc(project.buses.find(b=>b.id===project.selectedBus)?.name||'Choose a bus')}</h2></div><a href="#results">Source contributions & math →</a></div>${pending?'<p>Calculate to update the current inputs.</p>':contributionView(r)}</section></aside></div>${settingsView()}${reviewView()}`}
