function cloudProjectsView(){const state=cloud.state;return `<section class="panel cloud-projects"><div class="panel-heading"><div><span class="eyebrow">PRIVATE SAVED STUDIES</span><h2>Open your work on another device</h2></div><div class="actions"><button data-action="cloud-backup" ${!state.available?'disabled':''} title="Export all cloud saved studies and revision history to your device">Export full cloud backup JSON</button><button data-action="cloud-refresh" ${cloudListLoading||!state.available?'disabled':''}>Refresh</button></div></div><p>Save once to keep this study across devices. Later edits autosave to its next revision. Double-click equipment on the single line to edit its properties. <strong>Full backup exports only cloud-saved cases and their history. An unsaved device draft must be exported separately.</strong></p><div class="cloud-search"><label for="cloud-search">Search saved studies<input id="cloud-search" type="search" value="${esc(cloudSearch)}" placeholder="Project, case, or notes" maxlength="1000"></label><label for="cloud-sort">Sort<select id="cloud-sort"><option value="updated_desc" ${cloudSort==='updated_desc'?'selected':''}>Most recently edited</option><option value="updated_asc" ${cloudSort==='updated_asc'?'selected':''}>Oldest edit first</option><option value="name" ${cloudSort==='name'?'selected':''}>Project / case name</option></select></label></div>${!state.available?`<p class="cloud-error" role="status">${esc(state.message)}</p><button data-action="refresh">Refresh private access</button>`:cloudListMessage?`<p class="cloud-error" role="alert">${esc(cloudListMessage)}</p>`:''}${cloudListLoading?'<p role="status">Loading saved studies…</p>':cloudRows.map(row=>`<article class="cloud-case"><div class="cloud-case-heading"><div><h3>${esc(row.projectName)}</h3><strong>${esc(row.caseName)}</strong><small>Revision ${row.revision} · Updated ${esc(new Date(row.updatedAt).toLocaleString())}<br>Created ${esc(new Date(row.createdAt).toLocaleString())}</small></div>${row.id===state.active?.id?'<span class="badge">Current study</span>':''}</div><div class="actions"><button class="primary" data-cloud-open="${row.id}">Open / Edit</button><button data-cloud-rename="${row.id}">Rename</button><button data-cloud-copy="${row.id}">Duplicate</button><button data-cloud-scenario="${row.id}">Duplicate as scenario</button><button class="cloud-delete" data-cloud-delete="${row.id}">Delete</button></div>${deleteCaseId===row.id?`<div class="cloud-delete-confirm" role="alert">Delete “${esc(row.caseName)}” and its saved revisions?<div class="actions"><button class="danger" data-cloud-confirm-delete="${row.id}">Delete saved study</button><button data-action="cloud-cancel-delete">Keep study</button></div></div>`:''}</article>`).join('')||(state.available?'<p>No saved studies match this search.</p>':'')}<div class="actions"><button data-action="cloud-prev" ${cloudOffset===0?'disabled':''}>← Previous</button><button data-action="cloud-next" ${!cloudMore?'disabled':''}>Next →</button></div></section>`}
async function refreshCloudList(){if(!cloud.state.available)return;const request=++cloudListRequest;cloudListLoading=true;cloudListMessage='';if(view==='projects')render();try{const data=await cloud.list({search:cloudSearch,sort:cloudSort,offset:cloudOffset});if(request!==cloudListRequest)return;cloudRows=data.cases;cloudMore=data.hasMore;}catch(error){if(request!==cloudListRequest)return;cloudListMessage=error.message;}if(request===cloudListRequest){cloudListLoading=false;if(view==='projects')render();}}
async function backupForReplace(){const startRevision=revision,startProject=project.id;if(!saveNamed())return false;try{if(cloudHosted&&!cloud.state.conflict)await cloud.flush();if(startRevision!==revision||startProject!==project.id)throw Error('The current study changed while saving. Try opening the other study again.');return true;}catch(error){notice=esc(error.message);render();return false;}}
