async function prepareBrowserHandoff(){
 if(!commitFocusedField())return;
 const browserTab=reserveBrowserTab();let navigated=false;
 persist();const request=++browserHandoffRequest,currentId=project.id,snapshot=canonicalStudy(project),target=view;
 browserHandoff={phase:'preparing',projectId:currentId,snapshot};render();
 try{
  if(!cloud.state.available)throw Error(cloud.state.message||'Private saved studies are unavailable. Refresh private access and retry.');
  const row=await cloud.save();if(request!==browserHandoffRequest||project.id!==currentId)return;
  if(row.stale||canonicalStudy(row.data)!==snapshot||canonicalStudy(project)!==snapshot)throw Error('The study changed while saving. Click Open this study in browser again.');
  browserHandoff={phase:'ready',projectId:currentId,snapshot,url:studyBrowserURL(row,target),revision:row.revision};render();
  if(browserTab&&!browserTab.closed){try{browserTab.location.replace(browserHandoff.url);navigated=true;}catch{}}
 }catch(error){if(request===browserHandoffRequest&&project.id===currentId){browserHandoff={phase:'error',projectId:currentId,snapshot,message:error.message};render();}}
 finally{if(browserTab&&!navigated)try{browserTab.close();}catch{}}
}
async function copyBrowserAddress(selector){const field=document.querySelector(selector);if(!field?.value)return;let copied=false;try{if(!globalThis.navigator?.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(field.value);copied=true;notice='Address copied. Paste it into your browser address bar.';}catch{notice='Select and copy the address below, then paste it into your browser address bar.';}render();if(!copied){const fresh=document.querySelector(selector);fresh?.focus?.({preventScroll:true});fresh?.select?.();}}
async function cloudCaseAction(dataset){const key=['cloudOpen','cloudRename','cloudCopy','cloudScenario','cloudDelete','cloudConfirmDelete'].find(k=>dataset[k]);if(!key)return false;const caseId=dataset[key];if(key==='cloudOpen'||key==='cloudRename'){await openCloudStudy(caseId,key==='cloudRename');return true;}const row=cloudRows.find(x=>x.id===caseId);if(!row)return true;if(key==='cloudDelete'){deleteCaseId=caseId;render();return true;}try{if(key==='cloudConfirmDelete'){await cloud.remove(row);deleteCaseId=null;notice='Saved study deleted. A current workspace copy remains available for a new save.';}else{if(cloud.state.active?.id===row.id){await cloud.flush();row.revision=cloud.state.active.revision;}const copy=await cloud.duplicate(row,key==='cloudScenario');notice='Created '+esc(copy.caseName)+'. Open it to edit its Inputs and scenario.';}await refreshCloudList();render();}catch(error){notice=esc(error.message);render();}return true;}
function releaseReportLink(){if(!reportDownload?.url)return;const url=reportDownload.url;const timer=setTimeout(()=>URL.revokeObjectURL(url),30000);timer?.unref?.();}
