function saveNamed(){const saved=read('fault-network-studies-v2',[]);saved.unshift({saved:new Date().toISOString(),project:clone(project)});const ok=write('fault-network-studies-v2',saved);notice=ok?'Study saved. Export JSON for a portable backup.':'Could not save to browser storage. Export JSON to keep this study.';render();return ok}
function startDownloadURL(name,url){const a=document.createElement('a');a.href=url;a.download=name;document.body?.appendChild?.(a);try{a.click();}finally{a.remove?.();}}
function download(name,text,type){const u=URL.createObjectURL(text instanceof Blob?text:new Blob([text],{type}));startDownloadURL(name,u);setTimeout(()=>URL.revokeObjectURL(u),1000);}
